// Code by Flopine

// Thanks to wsmind, leon, XT95, lsdlive, lamogui, 
// Coyhot, Alkama,YX, NuSan, slerpy, wwrighter 
// BigWings, FabriceNeyret and Blackle for teaching me

// Thanks LJ for giving me the spark :3

// Thanks to the Cookie Collective, which build a cozy and safe environment for me 
// and other to sprout :)  
// https://twitter.com/CookieDemoparty


// Genuary #18: What does wind look like?

#define t (iTime*0.25)
#define TAU (2.*acos(-1.))
#define rot(a) mat2(cos(a), sin(a), -sin(a), cos(a))

#define nono(u) texNoise(texNoise(u*.5).xy-t*.2).xyz

#define AAstep(thre, val) smoothstep(-.7,.7,(val-thre)/min(0.02,fwidth(val-thre)))

#define pal(t,d) (vec3(.5)+vec3(0.5)*cos(TAU*(t+d)))

// taken from YX here : https://www.shadertoy.com/view/tdlXW4
// rough shadertoy approximation of the bonzomatic noise texture
vec4 texNoise(vec2 uv)
{
    float f = 0.;
    f += texture(iChannel0, uv*.125).r*.5;
    f += texture(iChannel0, uv*.25).r*.25;
    f += texture(iChannel0, uv*.5).r*.125;
    f += texture(iChannel0, uv*1.).r*.125;
    f=pow(f,1.2);
    return vec4(f*.45+.05);
}

// iq article
// https://iquilezles.org/articles/distfunctions2d/
float ndot(vec2 a, vec2 b ) { return a.x*b.x - a.y*b.y; }
float sdRhombus( in vec2 p, in vec2 b ) 
{
    p = abs(p);
    float h = clamp( ndot(b-2.0*p,b)/dot(b,b), -1.0, 1.0 );
    float d = length( p-0.5*b*vec2(1.0-h,1.0+h) );
    return d * sign( p.x*b.y + p.y*b.x - b.x*b.y );
}

float s = 0.;
float frame (vec2 uv)
{
    vec2 id = floor(uv);
    uv = fract(uv)-.5;
    id += 5.;

    vec3 n = nono(id*0.015)*2. - 1.;
    s = dot(vec2(1.), n.xy);
    uv *= rot(s*TAU);

    return AAstep(.03,abs(sdRhombus(uv, vec2(0.2, 0.42))));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (2.*fragCoord-iResolution.xy)/iResolution.y;

    vec3 col = vec3(1.-frame(uv*15.));
    col -= pal(s, vec3(.0, .63, .37));
    fragColor = vec4(sqrt(clamp(col,0., 1.)),1.0);
}
